def get_ranking(vocab_size: int) -> tuple[list[int], str] | None:
    """The bundled ranking for ``vocab_size`` and its source, or None."""
    entry = _RANKINGS.get(vocab_size)
    if entry is None:
        return None
    source, sha256, data = entry
    raw = zlib.decompress(base64.b85decode(data))
    if hashlib.sha256(raw).hexdigest() != sha256:
        raise ValueError(f"draft vocab ranking for vocab {vocab_size} is corrupt")
    ids = [int.from_bytes(raw[i : i + 4], "little") for i in range(0, len(raw), 4)]
    return ids, source
